#### From mathcomp Require Import all_ssreflect all_algebra. From mathcomp Require Import reals geometry. Set Implicit Arguments. Unset Strict Implicit. Unset Printing Implicit Defensive. Section Putnam_Geometry_Problem. Variable R : realType. Record point := Point { px : R; py : R }. Definition collinear (A B C : point) : Prop := (px B - px A) * (py C - py A) = (px C - px A) * (py B - py A). Definition perpendicular (A B C : point) : Prop := ((px B - px A) * (px C - px A) + (py B - py A) * (py C - py A)) = 0. Definition on_line (P A B : point) : Prop := collinear A B P. Definition between (A B C : point) : Prop := collinear A B C /\ ((px A <= px B <= px C) / (px C <= px B <= px A) / (py A <= py B <= py C) / (py C <= py B <= py A)). Definition dist (A B : point) : R := Num.sqrt ((px A - px B)^+2 + (py A - py B)^+2). Theorem rectangle_construct : forall A B C D : point, perpendicular A B C -> perpendicular B C D -> perpendicular C D A -> perpendicular D A B -> dist A B = dist C D -> dist B C = dist D A -> exists E : point, between A E C /\ between B E D. Proof. admit. Qed. End Putnam_Geometry_Problem.
